### 阶段级延迟 profiling（可直接套在自己的 VLA 上）

```python
import time
import torch

def cuda_timed(fn, warmup=10, repeat=50):
    for _ in range(warmup):
        fn()
    torch.cuda.synchronize()
    t0 = time.perf_counter()
    for _ in range(repeat):
        fn()
    torch.cuda.synchronize()
    return (time.perf_counter() - t0) / repeat * 1000.0   # ms

def profile_vla(model, dummy_batch, stages, use_graphs=False):
    # stages: [(name, fn), ...] 按推理链路切分
    report = {}
    for name, fn in stages:
        report[name] = cuda_timed(fn)
    total = sum(report.values())
    for k in report:
        report[k + '_pct'] = round(100.0 * report[k] / total, 1)
    report['total_ms'] = round(total, 3)
    report['max_hz'] = round(1000.0 / total, 1)
    return report

# 优化交互矩阵：逐项收益 vs 组合收益
def interaction_matrix(run_fn, opts, base_ms):
    # opts: [(name, apply_fn), ...]
    single = {}
    for name, apply in opts:
        single[name] = base_ms - run_fn([apply])
    combo = {}
    for i, (n1, a1) in enumerate(opts):
        for n2, a2 in opts[i + 1:]:
            gain_pair = base_ms - run_fn([a1, a2])
            combo[n1 + '+' + n2] = {
                'measured': round(gain_pair, 3),
                'naive_sum': round(single[n1] + single[n2], 3),
                'interaction': round(gain_pair - single[n1] - single[n2], 3),
            }
    return single, combo

